 counts=collections.Counter(a['path'].get('stage','path') for a in u['approaches']);prefix=sum(a['path'].get('valid_prefix_collision_check',{}).get('sampled_poses',0) for a in u['approaches']);hits=collections.Counter(a['path'].get('valid_prefix_collision_check',{}).get('first_collision',{}).get('obstacle') for a in u['approaches']);lines.append(f'- {u["variant"]}: {u["summary"]["attempts"]} path templates, **0 complete clear paths**; {dict(counts)}; {prefix} reachable-prefix sample checks; first-obstacle counts {dict(hits)}.')
